// Test helpers: start server.mjs as a child process and talk HTTP to it.
import { spawn } from 'node:child_process';
import { mkdtemp, writeFile } from 'node:fs/promises';
import { request as httpRequest } from 'node:http';
import { connect, createServer as createNetServer } from 'node:net';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

export const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
export const SERVER = join(ROOT, 'server.mjs');
export const LISTEN_RE = /^listening on http:\/\/127\.0\.0\.1:(\d+)\n$/;
export const JSON_TYPE = 'application/json; charset=utf-8';
export const JSON_HEADERS = Object.freeze({ 'Content-Type': 'application/json' });
const EXIT_TIMEOUT_MS = 5000;

/** A valid booking body; override any field. */
export const booking = (overrides = {}) => ({
  room: 'Aurora',
  title: 'Standup',
  date: '2026-11-03',
  start: '09:00',
  end: '10:00',
  ...overrides,
});

export const makeTmpDir = () => mkdtemp(join(tmpdir(), 'rooms-test-'));

/** Writes a data file in the server's layout. */
export const writeStore = (path, bookings = [], nextId = bookings.length + 1) =>
  writeFile(path, JSON.stringify({ nextId, bookings }));

/** Environment without the caller's PORT / DATA_FILE; `undefined` values mean unset. */
function buildEnv(env) {
  const base = { ...process.env };
  delete base.PORT;
  delete base.DATA_FILE;
  const merged = { ...base, ...env };
  return Object.fromEntries(Object.entries(merged).filter(([, v]) => v !== undefined));
}

/** Spawns the server. Returns a handle with live stdout/stderr text and an exit promise. */
export function spawnServer({ cwd, env = {}, script = SERVER }) {
  const child = spawn(process.execPath, [script], { cwd, env: buildEnv(env) });
  const out = { stdout: '', stderr: '' };
  child.stdout.setEncoding('utf8').on('data', (d) => (out.stdout += d));
  child.stderr.setEncoding('utf8').on('data', (d) => (out.stderr += d));
  const exited = new Promise((resolve) => {
    child.on('close', (code, signal) => resolve({ code, signal }));
  });
  return {
    child,
    exited,
    stdout: () => out.stdout,
    stderr: () => out.stderr,
  };
}

/** Runs the server until it exits by itself; fails if it is still running after the timeout. */
export async function runToExit(opts, timeoutMs = EXIT_TIMEOUT_MS) {
  const handle = spawnServer(opts);
  let timer;
  const timeout = new Promise((resolve) => {
    timer = setTimeout(() => resolve('timeout'), timeoutMs);
  });
  const result = await Promise.race([handle.exited, timeout]);
  clearTimeout(timer);
  if (result === 'timeout') {
    handle.child.kill('SIGKILL');
    await handle.exited;
    throw new Error(`server did not exit; stdout=${JSON.stringify(handle.stdout())}`);
  }
  return { code: result.code, signal: result.signal, stdout: handle.stdout(), stderr: handle.stderr() };
}

/**
 * Starts the server (PORT=0 unless given) and waits for the listening line.
 * Returns { port, stop(), stdout(), stderr(), child }.
 */
export async function startServer({ cwd, env = {} }) {
  const handle = spawnServer({ cwd, env: { PORT: '0', ...env } });
  const port = await new Promise((resolve, reject) => {
    const onData = () => {
      const match = LISTEN_RE.exec(handle.stdout());
      if (match) resolve(Number(match[1]));
    };
    handle.child.stdout.on('data', onData);
    handle.exited.then(({ code }) =>
      reject(new Error(`server exited (${code}) before listening: ${handle.stderr()}`)),
    );
  });
  const stop = async () => {
    if (handle.child.exitCode === null && handle.child.signalCode === null) {
      handle.child.kill();
    }
    await handle.exited;
  };
  return { ...handle, port, stop };
}

/**
 * One HTTP request with a raw path (sent as given, nothing normalised).
 * Resolves to { status, headers, text, json } (json is undefined when the body is not JSON).
 */
export function request(port, { method = 'GET', path = '/', headers = {}, body } = {}) {
  return new Promise((resolve, reject) => {
    const req = httpRequest(
      { host: '127.0.0.1', port, method, path, headers, agent: false },
      (res) => {
        const chunks = [];
        res.on('data', (c) => chunks.push(c));
        res.on('end', () => {
          const text = Buffer.concat(chunks).toString('utf8');
          let json;
          try {
            json = JSON.parse(text);
          } catch {
            json = undefined;
          }
          resolve({ status: res.statusCode, headers: res.headers, text, json });
        });
        res.on('error', reject);
      },
    );
    req.on('error', reject);
    req.end(body);
  });
}

/** POST /api/bookings with a JSON body (object, or a raw string/Buffer). */
export function postBooking(port, value, headers = JSON_HEADERS) {
  const body = typeof value === 'string' || Buffer.isBuffer(value) ? value : JSON.stringify(value);
  return request(port, { method: 'POST', path: '/api/bookings', headers, body });
}

export const getBookings = async (port, query = '') =>
  (await request(port, { path: `/api/bookings${query}` })).json.bookings;

/**
 * Writes raw bytes to a socket and resolves to everything the server sent back
 * once it closes the connection (send `Connection: close`).
 */
export function rawRequest(port, data) {
  return new Promise((resolve, reject) => {
    const socket = connect(port, '127.0.0.1');
    const chunks = [];
    socket.on('data', (c) => chunks.push(c));
    socket.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    socket.on('error', reject);
    socket.write(data);
  });
}

/** Opens a socket and returns it plus a getter for the bytes received so far. */
export function openSocket(port) {
  return new Promise((resolve, reject) => {
    const socket = connect(port, '127.0.0.1', () => resolve({ socket, received: () => text }));
    let text = '';
    socket.setEncoding('utf8');
    socket.on('data', (d) => (text += d));
    socket.on('error', reject);
  });
}

/** Resolves true when 127.0.0.1:<port> can be bound right now. */
export function isPortFree(port) {
  return new Promise((resolve) => {
    const probe = createNetServer();
    probe.once('error', () => resolve(false));
    probe.listen(port, '127.0.0.1', () => probe.close(() => resolve(true)));
  });
}

/** Binds a port (0 = any) on 127.0.0.1 and returns { port, close() }. */
export function occupyPort(port = 0) {
  return new Promise((resolve, reject) => {
    const blocker = createNetServer();
    blocker.once('error', reject);
    blocker.listen(port, '127.0.0.1', () =>
      resolve({
        port: blocker.address().port,
        close: () => new Promise((done) => blocker.close(() => done())),
      }),
    );
  });
}

export const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// A minimal fake browser for public/app.js: only the APIs the spec allows.
// Any other member the script touches is recorded in `page.violations` (and throws).
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import vm from 'node:vm';
import { ROOT } from './server.mjs';

export const APP_PATH = join(ROOT, 'public', 'app.js');

const ELEMENT_MEMBERS = new Set([
  'textContent', 'value', 'type', 'disabled', 'append', 'replaceChildren', 'addEventListener',
]);
const PAGE_ELEMENTS = [
  ['booking-form', 'form'], ['room', 'select'], ['title', 'input', 'text'], ['date', 'input', 'date'],
  ['start', 'input', 'time'], ['end', 'input', 'time'], ['book', 'button', 'submit'],
  ['filter-date', 'input', 'date'], ['show-all', 'button', 'button'], ['booking-list', 'ul'],
  ['error', 'p'],
];

export class TextNode {
  constructor(data) {
    this.nodeType = 3;
    this.data = String(data);
  }
}

/** Test-side element. The script only ever sees `el.proxy`. */
export class FakeElement {
  constructor(page, tag, { id = null, type = '' } = {}) {
    this.page = page;
    this.tag = tag;
    this.id = id;
    this.type = type;
    this.disabled = false;
    this.childNodes = [];
    this.listeners = {};
    this.storedValue = '';
    this.proxy = page.wrap(this, this.label(), ELEMENT_MEMBERS);
  }

  label() {
    return this.id ? `#${this.id}` : `<${this.tag}>`;
  }

  get value() {
    if (this.tag === 'select' && this.storedValue === '' && this.childNodes.length > 0) {
      return this.childNodes[0].value;
    }
    return this.storedValue;
  }

  set value(v) {
    this.storedValue = String(v);
  }

  get textContent() {
    return this.childNodes.map((n) => (n instanceof TextNode ? n.data : n.textContent)).join('');
  }

  set textContent(v) {
    const text = String(v);
    this.childNodes = text === '' ? [] : [new TextNode(text)];
  }

  get children() {
    return this.childNodes.filter((n) => n instanceof FakeElement);
  }

  toNodes(items) {
    return items.map((item) => {
      if (typeof item === 'string') return new TextNode(item);
      const el = this.page.unwrap(item);
      if (!el) throw new TypeError('append/replaceChildren got a non-node');
      return el;
    });
  }

  append(...items) {
    this.childNodes = [...this.childNodes, ...this.toNodes(items)];
  }

  replaceChildren(...items) {
    this.childNodes = this.toNodes(items);
  }

  addEventListener(type, fn) {
    this.listeners[type] = [...(this.listeners[type] ?? []), fn];
  }

  /** Test-side: fire an event; resolves to the event (see `defaultPrevented`). */
  dispatch(type) {
    const event = { type, defaultPrevented: false, preventDefaultCalls: 0 };
    const exposed = this.page.wrap(
      { preventDefault: () => { event.defaultPrevented = true; event.preventDefaultCalls += 1; } },
      `${type} event`, new Set(['preventDefault']),
    );
    for (const fn of this.listeners[type] ?? []) fn.call(this.proxy, exposed);
    return event;
  }

  /** Test-side: a click is dispatched like the browser, except disabled buttons get none. */
  click() {
    return this.dispatch('click');
  }
}

function makeResponse(page, status, json) {
  return page.wrap({ status, json }, 'response', new Set(['status', 'json']));
}

/** One recorded fetch call, settled by the test. */
class FetchCall {
  constructor(page, url, options) {
    this.page = page;
    this.url = url;
    this.options = options;
    this.method = options?.method ?? 'GET';
    this.promise = new Promise((resolve, reject) => {
      this.resolveFetch = resolve;
      this.rejectFetch = reject;
    });
  }

  /** Reply with a status and a JSON-able body (json() resolves to a copy). */
  reply(status, body) {
    const copy = body === undefined ? undefined : JSON.parse(JSON.stringify(body));
    const json = () => (body === undefined
      ? Promise.reject(new SyntaxError('Unexpected end of JSON input'))
      : Promise.resolve(copy));
    this.resolveFetch(makeResponse(this.page, status, json));
  }

  /** Reply whose body is not JSON: json() rejects. */
  replyNotJson(status) {
    this.resolveFetch(makeResponse(this.page, status, () => Promise.reject(new SyntaxError('bad json'))));
  }

  /** Reply whose body arrives later: returns { send(body), fail() }. */
  replyLater(status) {
    let settle;
    const bodyPromise = new Promise((resolve, reject) => { settle = { resolve, reject }; });
    this.resolveFetch(makeResponse(this.page, status, () => bodyPromise));
    return {
      send: (body) => settle.resolve(JSON.parse(JSON.stringify(body))),
      fail: () => settle.reject(new TypeError('body stream failed')),
    };
  }

  /** No reply at all (network error). */
  fail() {
    this.rejectFetch(new TypeError('Failed to fetch'));
  }
}

class FakePage {
  constructor() {
    this.violations = [];
    this.log = [];
    this.fetches = [];
    this.proxies = new WeakMap();
    this.elements = new Map();
    for (const [id, tag, type] of PAGE_ELEMENTS) {
      this.elements.set(id, new FakeElement(this, tag, { id, type }));
    }
  }

  el(id) {
    return this.elements.get(id);
  }

  unwrap(proxy) {
    return this.proxies.get(proxy);
  }

  /** Wraps a target so the script may use only `allowed` members; logs sets and calls. */
  wrap(target, label, allowed) {
    const page = this;
    const proxy = new Proxy(target, {
      get(t, prop) {
        if (typeof prop === 'symbol' || prop === 'then') return undefined;
        if (!allowed.has(prop)) return page.violate(`get ${label}.${prop}`);
        const value = t[prop];
        if (typeof value !== 'function') return value;
        return (...args) => {
          page.log.push(`${label}.${prop}()`);
          return value.apply(t, args);
        };
      },
      set(t, prop, value) {
        if (typeof prop === 'symbol' || !allowed.has(prop)) return page.violate(`set ${label}.${String(prop)}`);
        page.log.push(`${label}.${prop}=${JSON.stringify(value)}`);
        t[prop] = value;
        return true;
      },
      has: (t, prop) => allowed.has(prop),
      deleteProperty: (t, prop) => page.violate(`delete ${label}.${String(prop)}`),
      defineProperty: (t, prop) => page.violate(`define ${label}.${String(prop)}`),
    });
    this.proxies.set(proxy, target);
    return proxy;
  }

  violate(what) {
    this.violations.push(what);
    throw new Error(`app.js used a forbidden API: ${what}`);
  }

  makeDocument() {
    const doc = {
      getElementById: (id) => this.elements.get(id)?.proxy ?? null,
      createElement: (tag) => new FakeElement(this, String(tag).toLowerCase()).proxy,
    };
    return this.wrap(doc, 'document', new Set(['getElementById', 'createElement']));
  }

  makeFetch() {
    return (url, options) => {
      const call = new FetchCall(this, url, options);
      this.log.push(`fetch ${call.method} ${url}`);
      this.fetches.push(call);
      return call.promise;
    };
  }

  /** Fetch calls whose URL is a bookings list request. */
  listFetches() {
    return this.fetches.filter((f) => f.method === 'GET' && /^\/api\/bookings(\?|$)/.test(f.url));
  }

  lastFetch() {
    return this.fetches[this.fetches.length - 1];
  }
}

/**
 * Loads public/app.js (or `source`) into a fresh fake page. The script's only
 * globals are `document` and `fetch` (plus the JS built-ins).
 */
export function loadApp({ source = readFileSync(APP_PATH, 'utf8'), setup } = {}) {
  const page = new FakePage();
  if (setup) setup(page);
  const context = vm.createContext({ document: page.makeDocument(), fetch: page.makeFetch() });
  new vm.Script(source, { filename: 'app.js' }).runInContext(context);
  return page;
}

/** Lets every pending promise chain run to the end. */
export async function flush() {
  for (let i = 0; i < 5; i += 1) await new Promise((resolve) => setImmediate(resolve));
}

/** Text of each child node of an element, as [kind, text] pairs. */
export const describeChildren = (el) =>
  el.childNodes.map((n) => (n instanceof TextNode ? ['text', n.data] : [n.tag, n.textContent]));

